-- 27 further authored original LF-05 question/guide candidates: HELD, never immediately exposed.
-- Source: current PR834 research head 3b318fc53bce95195c8eef8b5771690c123f2a31; historical independent A3 43620992688.
-- Stacked on #853 (six held) and approved #851 (six published), no AI mark awards.
begin;
create temporary table lf05_remaining27(id text,course_id text,paper_number smallint,topic_id text,skill_ref text,title text,question_prompt text,stimulus text,marks_style smallint,guidance jsonb,approved_source_ref text,approved_review_ref text) on commit drop;
do $$
begin
 if (select count(*) from public.lf05_written_questions)<>12
 or (select count(*) from public.lf05_written_guides)<>12
 or (select count(*) from lf05_remaining27)<>27
 or exists(select 1 from public.lf05_written_questions where id in (select id from lf05_remaining27))
 then raise exception 'LF-05 remaining candidate staging prerequisite failed';end if;
end $$;
select id,course_id,paper_number,topic_id,skill_ref,title,question_prompt,stimulus,marks_style,
encode(sha256(convert_to(id||chr(31)||question_prompt||chr(31)||coalesce(stimulus,'')||chr(31)||guidance::text,'UTF8')),'hex'),
true,'held',approved_source_ref from lf05_remaining27;
select q.id,q.content_fingerprint,s.guidance,s.approved_review_ref
from lf05_remaining27 s join public.lf05_written_questions q on q.id=s.id;
commit;
